"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "orders",
    "uid": "uid-deployment-orders"
  },
  "params": {
    "container": "app",
    "readiness": {
      "initialDelaySeconds": 5,
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increased readiness probe timeout and initial delay to allow app to start and respond before probe failures.",
  "rationale": "Readiness probe failures with 503 indicate the app is up but not ready. The current timeout (2s) is likely too short for the app's startup latency. Increasing both initialDelaySeconds and timeoutSeconds to 5s provides a buffer for the app to initialize before probes start failing.",
